 private void write(String name,Object value)throws Exception{var p=dir.resolve(name);var t=p.resolveSibling(name+".tmp");Files.writeString(t,new Gson().toJson(value));for(int retry=0;;retry++){try{Files.move(t,p,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);break;}catch(java.nio.file.AccessDeniedException locked){if(retry>=99)throw locked;java.util.concurrent.locks.LockSupport.parkNanos(1000000);}}}
 private JsonObject read(String name)throws Exception{return JsonParser.parseString(Files.readString(dir.resolve(name))).getAsJsonObject();}
 private void command(int i,String action,Object...args)throws Exception{var j=new JsonObject();j.addProperty("nonce",++nonce);sent[i]=nonce;j.addProperty("action",action);for(int n=0;n<args.length;n+=2)j.addProperty(args[n].toString(),args[n+1].toString());write(names[i]+".command.json",j);}
 private boolean ack(int i)throws Exception{return Files.exists(dir.resolve(names[i]+".reply.json"))&&read(names[i]+".reply.json").get("nonce").getAsLong()==sent[i];}
